import {React, useState, useEffect} from 'react';
import { Table } from 'rsuite';

const TableRides = (props) => {
    const [error, setError] = useState(null);
    const [isLoaded, setIsLoaded] = useState(false);
    const [data, setData] = useState([]);
    const [columnsVisible, setColumnsVisible] = useState(props.columnsVisible);
    const [titleTable, setTitleTable] = useState(props.title);
    const { Column, HeaderCell, Cell } = Table;
    const [sortColumn, setSortColumn] = React.useState();
    const [sortType, setSortType] = React.useState();
    const [loading, setLoading] = React.useState(false);
    useEffect(() => {
        fetch("http://127.0.0.1:3001/covoiturafpa/rides")
        .then(res => res.json())
        .then(
            (result) => {
            setIsLoaded(true);
            console.log(result);
            setData([result]);
            },
            // Remarque : il faut gérer les erreurs ici plutôt que dans
            // un bloc catch() afin que nous n’avalions pas les exceptions
            // dues à de véritables bugs dans les composants.
            (error) => {
            setIsLoaded(true);
            setError(error);
            }
        )
    }, [])


  const getData = () => {
    if (sortColumn && sortType) {
      return data.sort((a, b) => {
        let x = a[sortColumn];
        let y = b[sortColumn];
        if (typeof x === 'string') {
          x = x.charCodeAt();
        }
        if (typeof y === 'string') {
          y = y.charCodeAt();
        }
        if (sortType === 'asc') {
          return x - y;
        } else {
          return y - x;
        }
      });
    }
    return data;
  };

  const handleSortColumn = (sortColumn, sortType) => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setSortColumn(sortColumn);
      setSortType(sortType);
    }, 500);
  };

  if (error) {
    return <div>Erreur : {error.message}</div>;
  } else if (!isLoaded) {
    return <div>Chargement...</div>;
  } else {
    return (
        <div>
            <h1>{titleTable}</h1>
            <Table
            height={400}
            data={data[0]}
            onRowClick={rowData => {
                console.log(rowData);
            }}>
                <Column width={60} align="center" fixed>
                    <HeaderCell>Id</HeaderCell>
                    <Cell dataKey="id_ride" />
                </Column>
                <Column width={150}>
                    <HeaderCell>Activé</HeaderCell>
                    <Cell dataKey="is_active" />
                </Column>

                <Column width={150}>
                    <HeaderCell>heure de départ</HeaderCell>
                    <Cell dataKey="departure_time" />
                </Column>

                <Column width={100}>
                    <HeaderCell>Commentaire</HeaderCell>
                    <Cell dataKey="Comment" />
                </Column>
                <Column width={80} fixed="right">
                    <HeaderCell>...</HeaderCell>
                    <Cell>
                    {rowData => (
                        <span>
                        <a onClick={() => alert(`id:${rowData.id}`)}> Edit </a>
                        </span>
                    )}
                    </Cell>
                </Column>
            </Table>
        </div>
        
    );
  }

    
}
export { TableRides };
